/* Level 13 (Gemlik Base) code following partupd; generated by tools/overlay_src.py, stubs replaced by C as functions
   are matched. Starts at 0x002811B0 (was partupd_002811B0.c). */
#include "common.h"
#include "structs/particle.h"
#include "structs/moby.h"
#include "include_asm.h"
#include "asm_functions/executable.h"
#include "overlays/shared/moby_frame_packet.h"

extern int truncate_float_to_s32(float);

extern unsigned char *gemlik_part_type68_textures;

/* Allocates and fills a particle-process record attached to a moby. */
unsigned char *create_moby_joint_particle(char *moby, unsigned char a, int b, int c, unsigned char d, float x, float y,
                                          float z) {
    unsigned char *e = create_part(0x44);
    if (e != 0) {
        char *p;
        int v;
        unsigned short t;
        unsigned char *s;
        ((struct PartBase *)e)->color = b;
        *(int *)&((struct PartBase *)e)->size = c;
        p = (unsigned char *)&((struct PartBase *)e)->pos;
        v = truncate_float_to_s32(0.4f);
        ((struct PartBase *)e)->unk_09 = (((short)*(unsigned short *)&((struct Moby *)moby)->draw_dist >> 5) << 4) + v;
        ((struct PartBase *)e)->blend = 0x48;
        ((struct PartBase *)e)->unk_01 = 3;
        ((struct PartBase *)e)->texture = *gemlik_part_type68_textures;
        moby_point_position(moby, a, p);
        qcopy(((struct PartBase *)e)->data, p);
        *(float *)(e + 0x2C) = y;
        ((struct PartBase *)e)->pos.f[3] = x;
        *(char **)(e + 0x30) = moby;
        s = e + 0x30;
        t = *(unsigned short *)&((struct Moby *)moby)->oclass;
        *(short *)(s + 6) = t;
        s[4] = a;
        *(float *)(s + 8) = x;
        *(float *)(s + 0xC) = z;
        s[5] = d;
    }
    return e;
}
